        private static readonly Dictionary<string, Geometry> Parsed = new();

        /// <summary>The outline of the icon `name` (a key above).</summary>
        public static Geometry Geometry(string name)
        {
            if (!Parsed.TryGetValue(name, out var g)) Parsed[name] = g = StreamGeometry.Parse(Paths[name]);
            return g;
        }

        /// <summary>The icon `name` as a control (16 x 16).</summary>
        public static PathIcon Create(string name, double size = 16) => new() { Data = Geometry(name), Width = size, Height = size };

        /// <summary>Puts the icon `name` on the button (instead of its text) and gives it the tip.</summary>
        public static T Set<T>(T button, string name, string? tip = null) where T : ContentControl
        {
            button.Content = Create(name);
            if (tip != null) ToolTip.SetTip(button, tip);
            return button;
        }

        /// <summary>A tool bar button with the icon `name`.</summary>
        public static Button Button(string name, string tip, System.Action click)
        {
            var b = Set(new Button(), name, tip);
            b.Classes.Add("tool");
            b.Click += (_, _) => click();
            return b;
        }

        /// <summary>A tool bar switch with the icon `name`.</summary>
        public static ToggleButton Toggle(string name, string tip, bool on = false)
        {
            var b = Set(new ToggleButton { IsChecked = on }, name, tip);
            b.Classes.Add("tool");
            return b;
        }
    }
